# -*- coding: utf-8 -*-
TIER2_HEAD = r'<b>【 แบบที่ 2 ▸ พื้นฐาน · กระชับ · สูตรผลบวกมุม $45^\circ$ กับ $30^\circ$ (angle-sum formula) 】</b>'
TIER2 = [
    r'🎯 <b>เหมาะกับ</b> เด็กปานกลางถึงเก่ง · จำค่ามุมพิเศษกับสูตรผลบวกมุมได้แล้ว ต้องการเส้นทางสั้นที่สุดที่เดินถึงค่า $a$',
    r'<b>ขั้นที่ 1:</b> แตกมุม $75^\circ$ เป็นผลบวกของมุมพิเศษสองมุมที่รู้ค่าทั้งคู่',
    r'⇒ $75^\circ = 45^\circ + 30^\circ$ ⇒ $\sin 75^\circ = \sin\left(45^\circ + 30^\circ\right)$',
    r'<b>ขั้นที่ 2:</b> กางด้วยสูตร $\sin(A + B) = \sin A\cos B + \cos A\sin B$ โดยให้ $A = 45^\circ$ , $B = 30^\circ$',
    r'⇒ $\sin 75^\circ = \sin 45^\circ\cos 30^\circ + \cos 45^\circ\sin 30^\circ$',
    r'<b>ขั้นที่ 3:</b> แทนค่ามุมพิเศษ $\sin 45^\circ = \cos 45^\circ = \dfrac{\sqrt{2}}{2}$ , $\cos 30^\circ = \dfrac{\sqrt{3}}{2}$ , $\sin 30^\circ = \dfrac{1}{2}$ แล้วคูณกรณฑ์ด้วยกฎ $\sqrt{m} \cdot \sqrt{n} = \sqrt{mn}$',
    r'⇒ $\sin 75^\circ = \dfrac{\sqrt{2}}{2} \cdot \dfrac{\sqrt{3}}{2} + \dfrac{\sqrt{2}}{2} \cdot \dfrac{1}{2} = \dfrac{\sqrt{6}}{4} + \dfrac{\sqrt{2}}{4}$',
    r'<b>ขั้นที่ 4:</b> ยุบเป็นเศษส่วนเดียวให้ตัวส่วนเป็น $4$ เท่ากับรูปที่โจทย์บังคับ แล้วจับคู่สัมประสิทธิ์อ่านค่า $a$',
    r'⇒ $\dfrac{\sqrt{6} + \sqrt{2}}{4} = \dfrac{\sqrt{6} + \sqrt{a}}{4}$ ⇒ ตัด $\sqrt{6}$ ทั้งสองข้าง ⇒ $\sqrt{a} = \sqrt{2}$ ⇒ ยกกำลังสองได้ $a = 2$ ซึ่งเป็นจำนวนเต็มบวกจริง',
]
TIER3_HEAD = r'<b>【 แบบที่ 3 ▸ ⚡ ประยุกต์ · มุมครึ่งแล้วคลายรากซ้อน (half-angle then denesting) 】</b>'
TIER3 = [
    r'⚡ <b>เหมาะกับ</b> เด็กที่พื้นฐานคณิตดี มองเห็นว่า $75^\circ$ ผูกกับ $15^\circ$ ซึ่งเป็นครึ่งหนึ่งของมุมพิเศษ และคลายรากซ้อนเป็น',
    r'<b>ขั้นที่ 1:</b> ย้ายมุมด้วยมุมประกอบ $\sin\left(90^\circ - \theta\right) = \cos\theta$ ให้ไปตกที่มุมที่เป็นครึ่งของมุมพิเศษ',
    r'⇒ $\sin 75^\circ = \cos 15^\circ$ และ $15^\circ$ คือครึ่งหนึ่งของ $30^\circ$ ที่รู้ค่าอยู่แล้ว',
    r'<b>ขั้นที่ 2:</b> ใช้สูตรมุมครึ่ง $\cos\dfrac{\theta}{2} = \sqrt{\dfrac{1 + \cos\theta}{2}}$ ที่ $\theta = 30^\circ$ · เลือกรากบวกเพราะ $15^\circ$ อยู่ในจตุภาคที่ $1$',
    r'⇒ $\cos 15^\circ = \sqrt{\dfrac{1 + \cos 30^\circ}{2}} = \sqrt{\dfrac{2 + \sqrt{3}}{4}} = \dfrac{\sqrt{2 + \sqrt{3}}}{2}$',
    r'<b>ขั้นที่ 3:</b> คลายรากซ้อนให้เหลือกรณฑ์ชั้นเดียว โดยอ้าง $\sqrt{2 + \sqrt{3}} = \dfrac{\sqrt{6} + \sqrt{2}}{2}$ แล้วยืนยันด้วยการยกกำลังสองข้างขวา',
    r'⇒ $\left(\dfrac{\sqrt{6} + \sqrt{2}}{2}\right)^{2} = \dfrac{8 + 4\sqrt{3}}{4} = 2 + \sqrt{3}$ ✓ ตรงกับใต้กรณฑ์เดิม และทั้งสองข้างเป็นบวก จึงเท่ากันจริง',
    r'<b>ขั้นที่ 4:</b> แทนกลับเข้าไปแล้วจับคู่สัมประสิทธิ์',
    r'⇒ $\sin 75^\circ = \dfrac{1}{2} \cdot \dfrac{\sqrt{6} + \sqrt{2}}{2} = \dfrac{\sqrt{6} + \sqrt{2}}{4}$ ⇒ เทียบกับ $\dfrac{\sqrt{6} + \sqrt{a}}{4}$ ได้ $\sqrt{a} = \sqrt{2}$ ⇒ $a = 2$',
    r'<b>ข้อต่าง:</b> เดินด้วยค่ามุมพิเศษเพียงค่าเดียวคือ $\cos 30^\circ$ ไม่ต้องใช้ครบสี่ค่าและไม่ต้องกางสูตรผลบวกมุมเหมือนแบบที่ 1–2 แลกกับการต้องคลายรากซ้อนหนึ่งครั้ง',
]
